using ZosyalMedya.BuildingBlocks.Domain;
namespace ZosyalMedya.Modules.Communities.Domain.Communities;
public readonly record struct CommunityId(Guid Value){public static CommunityId New()=>new(Guid.NewGuid());}public readonly record struct CommunityActorId(Guid Value);
public enum CommunityVisibility{Public,Private,Hidden}public enum CommunityStatus{Active,Archived}public enum CommunityRole{Owner,Administrator,Moderator,Member}public enum MembershipStatus{Pending,Invited,Active,Removed}
public sealed class CommunityMember{private CommunityMember(){}internal CommunityMember(CommunityActorId id,CommunityRole role,MembershipStatus status,DateTimeOffset now){UserId=id;Role=role;Status=status;CreatedAtUtc=now;UpdatedAtUtc=now;}public CommunityActorId UserId{get;private set;}public CommunityRole Role{get;private set;}public MembershipStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}internal void Activate(DateTimeOffset now){Status=MembershipStatus.Active;UpdatedAtUtc=now;}internal void Invite(DateTimeOffset now){Status=MembershipStatus.Invited;UpdatedAtUtc=now;}internal void Remove(DateTimeOffset now){Status=MembershipStatus.Removed;UpdatedAtUtc=now;}internal void ChangeRole(CommunityRole role,DateTimeOffset now){Role=role;UpdatedAtUtc=now;}}
public sealed class CommunityRule{private CommunityRule(){Text=string.Empty;}internal CommunityRule(int order,string text){Order=order;Text=text;}public int Order{get;private set;}public string Text{get;private set;}}
public sealed class CommunityAuditEntry{private CommunityAuditEntry(){Action=Reason=string.Empty;}internal CommunityAuditEntry(long sequence,Guid actorId,string action,string reason,DateTimeOffset now){Sequence=sequence;ActorId=actorId;Action=action;Reason=reason;OccurredAtUtc=now;}public long Sequence{get;private set;}public Guid ActorId{get;private set;}public string Action{get;private set;}public string Reason{get;private set;}public DateTimeOffset OccurredAtUtc{get;private set;}}
public sealed partial class Community:AggregateRoot<CommunityId>
{private List<CommunityMember>_members=[];private List<CommunityRule>_rules=[];private List<Guid>_pinnedContentIds=[];private List<CommunityAuditEntry>_audit=[];private Community():base(default){Slug=Name=Description=string.Empty;}private Community(CommunityId id,CommunityActorId owner,string slug,string name,string description,CommunityVisibility visibility,DateTimeOffset now):base(id){Slug=NormalizeSlug(slug);Name=Validate(name,2,100,"communities.name_invalid");Description=Validate(description,0,2000,"communities.description_invalid");Visibility=visibility;Status=CommunityStatus.Active;CreatedAtUtc=UpdatedAtUtc=now;Version=1;_members.Add(new(owner,CommunityRole.Owner,MembershipStatus.Active,now));Audit(owner,"created","Topluluk oluşturuldu.",now);}public string Slug{get;private set;}public string Name{get;private set;}public string Description{get;private set;}public CommunityVisibility Visibility{get;private set;}public CommunityStatus Status{get;private set;}public IReadOnlyList<CommunityMember>Members=>_members.AsReadOnly();public IReadOnlyList<CommunityRule>Rules=>_rules.AsReadOnly();public IReadOnlyList<Guid>PinnedContentIds=>_pinnedContentIds.AsReadOnly();public IReadOnlyList<CommunityAuditEntry>AuditHistory=>_audit.AsReadOnly();public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}
 public static Community Create(CommunityId id,CommunityActorId owner,string slug,string name,string description,CommunityVisibility visibility,DateTimeOffset now){if(owner.Value==Guid.Empty)throw new DomainRuleException("communities.owner_invalid","Topluluk sahibi gereklidir.");return new(id,owner,slug,name,description,visibility,now);}public bool HasActiveMember(CommunityActorId id)=>_members.Any(x=>x.UserId==id&&x.Status==MembershipStatus.Active);public CommunityRole?RoleOf(CommunityActorId id)=>_members.SingleOrDefault(x=>x.UserId==id&&x.Status==MembershipStatus.Active)?.Role;
 public void Update(CommunityActorId actor,string name,string description,CommunityVisibility visibility,DateTimeOffset now){EnsureAdministrator(actor);EnsureActive();Name=Validate(name,2,100,"communities.name_invalid");Description=Validate(description,0,2000,"communities.description_invalid");Visibility=visibility;Touch(actor,"updated","Topluluk bilgileri güncellendi.",now);}public void RequestMembership(CommunityActorId actor,DateTimeOffset now){EnsureActive();var existing=_members.SingleOrDefault(x=>x.UserId==actor);if(existing?.Status==MembershipStatus.Active)return;if(Visibility==CommunityVisibility.Public){if(existing is null)_members.Add(new(actor,CommunityRole.Member,MembershipStatus.Active,now));else existing.Activate(now);}else{if(existing is null)_members.Add(new(actor,CommunityRole.Member,MembershipStatus.Pending,now));else if(existing.Status==MembershipStatus.Removed)throw new DomainRuleException("communities.membership_removed","Üyelik moderatör onayı gerektiriyor.");}Touch(actor,"membership_requested","Üyelik talebi.",now);}public void Invite(CommunityActorId actor,CommunityActorId target,DateTimeOffset now){EnsureAdministrator(actor);EnsureActive();var member=_members.SingleOrDefault(x=>x.UserId==target);if(member?.Status==MembershipStatus.Active)return;if(member is null)_members.Add(new(target,CommunityRole.Member,MembershipStatus.Invited,now));else member.Invite(now);Touch(actor,"member_invited",target.Value.ToString("D"),now);}public void Approve(CommunityActorId actor,CommunityActorId target,DateTimeOffset now){EnsureModerator(actor);EnsureActive();var member=RequireMember(target);if(member.Status is not(MembershipStatus.Pending or MembershipStatus.Invited))throw new DomainRuleException("communities.membership_state_invalid","Üyelik onaylanabilir durumda değil.");member.Activate(now);Touch(actor,"member_approved",target.Value.ToString("D"),now);}public void ChangeRole(CommunityActorId actor,CommunityActorId target,CommunityRole role,DateTimeOffset now){if(RoleOf(actor)!=CommunityRole.Owner)throw new DomainRuleException("communities.owner_required","Rolü yalnız topluluk sahibi değiştirebilir.");EnsureActive();if(role==CommunityRole.Owner)throw new DomainRuleException("communities.owner_transfer_explicit","Sahiplik açık transfer akışı gerektirir.");RequireActiveMember(target).ChangeRole(role,now);Touch(actor,"role_changed",$"{target.Value:D}:{role}",now);}public void RemoveMember(CommunityActorId actor,CommunityActorId target,string reason,DateTimeOffset now){EnsureModerator(actor);EnsureActive();var member=RequireActiveMember(target);if(member.Role==CommunityRole.Owner)throw new DomainRuleException("communities.owner_remove_forbidden","Topluluk sahibi çıkarılamaz.");member.Remove(now);Touch(actor,"member_removed",Validate(reason,2,500,"communities.reason_required"),now);}public void SetRules(CommunityActorId actor,IReadOnlyList<string>rules,DateTimeOffset now){EnsureAdministrator(actor);EnsureActive();if(rules.Count>20)throw new DomainRuleException("communities.rules_limit","En fazla 20 kural olabilir.");_rules=rules.Select((x,i)=>new CommunityRule(i+1,Validate(x,2,300,"communities.rule_invalid"))).ToList();Touch(actor,"rules_updated","Kurallar güncellendi.",now);}public void Pin(CommunityActorId actor,Guid contentId,bool pinned,DateTimeOffset now){EnsureModerator(actor);EnsureActive();if(pinned){if(!_pinnedContentIds.Contains(contentId)){if(_pinnedContentIds.Count>=10)throw new DomainRuleException("communities.pin_limit","En fazla 10 içerik sabitlenebilir.");_pinnedContentIds.Add(contentId);}}else _pinnedContentIds.Remove(contentId);Touch(actor,pinned?"content_pinned":"content_unpinned",contentId.ToString("D"),now);}public void Archive(CommunityActorId actor,string reason,DateTimeOffset now){if(RoleOf(actor)!=CommunityRole.Owner)throw new DomainRuleException("communities.owner_required","Arşivleme için sahiplik gerekir.");Status=CommunityStatus.Archived;Touch(actor,"archived",Validate(reason,2,500,"communities.reason_required"),now);}
 private CommunityMember RequireMember(CommunityActorId id)=>_members.SingleOrDefault(x=>x.UserId==id)??throw new DomainRuleException("communities.member_not_found","Üye bulunamadı.");private CommunityMember RequireActiveMember(CommunityActorId id){var m=RequireMember(id);if(m.Status!=MembershipStatus.Active)throw new DomainRuleException("communities.member_inactive","Üyelik aktif değil.");return m;}private void EnsureAdministrator(CommunityActorId a){if(RoleOf(a)is not(CommunityRole.Owner or CommunityRole.Administrator))throw new DomainRuleException("communities.admin_required","Yönetici yetkisi gerekir.");}private void EnsureModerator(CommunityActorId a){if(RoleOf(a)is not(CommunityRole.Owner or CommunityRole.Administrator or CommunityRole.Moderator))throw new DomainRuleException("communities.moderator_required","Moderatör yetkisi gerekir.");}private void EnsureActive(){if(Status!=CommunityStatus.Active)throw new DomainRuleException("communities.archived","Arşivlenmiş topluluk değiştirilemez.");}private void Touch(CommunityActorId actor,string action,string reason,DateTimeOffset now){UpdatedAtUtc=now;Version++;Audit(actor,action,reason,now);}private void Audit(CommunityActorId actor,string action,string reason,DateTimeOffset now)=>_audit.Add(new(_audit.Count+1,actor.Value,action,reason,now));private static string NormalizeSlug(string value){var x=value.Trim().ToLowerInvariant();if(x.Length is<3 or>50||x.Any(c=>!char.IsLetterOrDigit(c)&&c!='-'))throw new DomainRuleException("communities.slug_invalid","Topluluk adresi 3-50 karakter, harf/rakam/tire olmalıdır.");return x;}private static string Validate(string value,int min,int max,string code){var x=value.Trim();if(x.Length<min||x.Length>max)throw new DomainRuleException(code,"Topluluk alanı geçersiz.");return x;}}
